const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
const text = data.toString('utf8', 0, Math.min(data.length, 1000000));

// Find all calendar event entries - search for known usernames
const users = ['olivia', 'priya', 'ethan', 'alice', 'bob', 'carol'];
for (const u of users) {
  let idx = 0;
  while ((idx = text.toLowerCase().indexOf(u, idx)) !== -1) {
    const context = text.substring(Math.max(0, idx - 50), Math.min(text.length, idx + 200));
    if (context.toLowerCase().includes('calendar') || context.toLowerCase().includes('event') || context.toLowerCase().includes('dtstart')) {
      console.log('--- Found near', u, 'at index', idx, '---');
      console.log(context);
      console.log();
    }
    idx += u.length;
  }
}
"

